import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased on its own line."""
    for s in xs:
        print(s.upper())


def test_shout_basic(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "World"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty_list(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_already_upper_and_mixed(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["ABC", "aBc", "a1!b"])
    assert capsys.readouterr().out == "ABC\nABC\nA1!B\n"


def test_shout_empty_string_prints_blank_line(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["", "x"])
    assert capsys.readouterr().out == "\nX\n"


def test_shout_preserves_order_and_duplicates(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["b", "a", "b"])
    assert capsys.readouterr().out == "B\nA\nB\n"


def test_shout_does_not_mutate_input() -> None:
    xs = ["abc", "def"]
    shout(xs)
    assert xs == ["abc", "def"]


def test_shout_unicode(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["straße", "é"])
    assert capsys.readouterr().out == "STRASSE\nÉ\n"
